@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private CustomerRepository customerRepo;
    @InjectMocks
    private OrderService orderService;

    @Test
    void testProcessOrder() {
        // Stub: return a customer for ANY email (matcher)
        when(customerRepo.findByEmail(anyString()))
            .thenReturn(new Customer("Alice"));

        var result = orderService.processOrder("alice@example.com");

        assertThat(result).isNotNull();
        // Verify: any email was passed, and the boolean was true
        verify(customerRepo).findByEmail(anyString());
        verify(customerRepo).updateStatus(any(Customer.class), eq(true));
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private OrderRepository orderRepo;
    @InjectMocks
    private PaymentService paymentService;

    @Test
    void testProcessHighValueOrders() {
        // Stub: return true for orders over 100 with PENDING status
        when(orderRepo.save(argThat(order -> 
            order != null && order.getTotal() > 100 && order.getStatus() == Status.PENDING
        ))).thenReturn(true);

        var order = new Order(1L, 150.0, Status.PENDING);
        boolean saved = paymentService.saveOrder(order);

        assertThat(saved).isTrue();
        verify(orderRepo).save(argThat(this::isHighValuePending));
    }

    private boolean isHighValuePending(Order order) {
        return order != null && order.getTotal() > 100 && order.getStatus() == Status.PENDING;
    }
}

@ExtendWith(MockitoExtension.class)
class NotificationServiceTest {
    @Mock
    private EmailSender emailSender;
    @Mock
    private SmsGateway smsGateway;
    @InjectMocks
    private NotificationService notificationService;

    @Test
    void testSendNotification() {
        var user = new User("alice@example.com", "+1234567890");
        notificationService.notifyUser(user, "Order shipped");

        // Verify email was sent with any string (we don't care about exact message)
        verify(emailSender).send(eq("alice@example.com"), anyString());
        // Verify SMS was sent with specific phone and any message
        verify(smsGateway).send(eq("+1234567890"), contains("shipped"));
        // Verify no other interactions
        verifyNoMoreInteractions(emailSender, smsGateway);
    }
}

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepo;
    @Captor
    private ArgumentCaptor<Order> orderCaptor;
    @InjectMocks
    private OrderService orderService;

    @Test
    void testPlaceOrder() {
        var customerId = 123L;
        orderService.placeOrder(customerId, List.of("item1", "item2"));

        // Capture the Order passed to save()
        verify(orderRepo).save(orderCaptor.capture());
        var capturedOrder = orderCaptor.getValue();

        // Assert on the captured object's properties
        assertThat(capturedOrder.getCustomerId()).isEqualTo(customerId);
        assertThat(capturedOrder.getItems()).hasSize(2);
        assertThat(capturedOrder.getStatus()).isEqualTo(OrderStatus.PENDING);
        assertThat(capturedOrder.getCreatedAt()).isCloseTo(LocalDateTime.now(), within(1, ChronoUnit.SECONDS));
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private PaymentGateway gateway;

    @Test
    void testMixingMatchers() {
        // WRONG: mixing matcher and raw value throws InvalidUseOfMatchersException
        // when(gateway.charge(anyString(), 100.0)).thenReturn(true);

        // CORRECT: all arguments are matchers
        when(gateway.charge(anyString(), eq(100.0))).thenReturn(true);

        // CORRECT: all arguments are raw values (no matchers)
        when(gateway.charge("user123", 100.0)).thenReturn(true);

        var result = gateway.charge("user456", 100.0);
        assertThat(result).isTrue();

        // Verify also requires all matchers or all raw values
        verify(gateway).charge(anyString(), eq(100.0));
    }
}

@ExtendWith(MockitoExtension.class)
class UserServiceTest {
    @Mock
    private UserRepository userRepo;
    @InjectMocks
    private UserService userService;

    @Test
    void testUpdateUser() {
        // Stub: return a user when findById is called with any Long, but updateStatus with exact status
        when(userRepo.findById(anyLong())).thenReturn(Optional.of(new User(1L, "Alice")));
        when(userRepo.updateStatus(anyLong(), eq(UserStatus.ACTIVE))).thenReturn(true);

        var result = userService.activateUser(1L);
        assertThat(result).isTrue();

        // Verify: any Long for ID, exact status using eq
        verify(userRepo).updateStatus(anyLong(), eq(UserStatus.ACTIVE));
        verify(userRepo, never()).updateStatus(anyLong(), eq(UserStatus.INACTIVE));
    }
}

// Class-based custom matcher
class HighValueOrderMatcher implements ArgumentMatcher<Order> {
    @Override
    public boolean matches(Order order) {
        return order != null && order.getTotal() > 500.0 && order.getStatus() == OrderStatus.PENDING;
    }
}

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepo;

    @Test
    void testCustomMatcher() {
        // Using class-based matcher
        when(orderRepo.save(argThat(new HighValueOrderMatcher()))).thenReturn(true);

        // Using lambda (one-off)
        when(orderRepo.process(argThat(order -> 
            order != null && order.getTotal() > 500.0
        ))).thenReturn("processed");

        verify(orderRepo).save(argThat(new HighValueOrderMatcher()));
    }
}
